<script setup>
import {computed,ref} from 'vue';
const props=defineProps({columns:Array,rows:Array,sortable:{type:Boolean,default:true}});const sortKey=ref(''),sortDirection=ref(1);
function sort(column){if(!props.sortable)return;if(sortKey.value===column.key)sortDirection.value*=-1;else{sortKey.value=column.key;sortDirection.value=1}}
function compare(a,b){if(a==null&&b==null)return 0;if(a==null)return 1;if(b==null)return-1;const na=Number(a),nb=Number(b);if(a!==''&&b!==''&&Number.isFinite(na)&&Number.isFinite(nb))return na-nb;return String(a).localeCompare(String(b),'zh-CN',{numeric:true})}
const displayedRows=computed(()=>{const values=[...(props.rows||[])];if(!props.sortable||!sortKey.value)return values;const column=props.columns.find(value=>value.key===sortKey.value),key=sortKey.value,direction=sortDirection.value;return values.sort((a,b)=>compare(column?.sortValue?column.sortValue(a):a[key],column?.sortValue?column.sortValue(b):b[key])*direction)});
</script>
<template><div v-if="!rows?.length" class="empty">暂无数据</div><div v-else class="table-wrap"><table><thead><tr><th v-for="c in columns" :key="c.key"><button v-if="sortable" class="sort-button" @click="sort(c)" :aria-label="`按${c.label}排序`"><span>{{c.label}}</span><i>{{sortKey===c.key?(sortDirection===1?'▲':'▼'):'↕'}}</i></button><template v-else>{{c.label}}</template></th></tr></thead><tbody><tr v-for="(row,i) in displayedRows" :key="row.id||i"><td v-for="c in columns" :key="c.key" :class="c.class?.(row[c.key])"><button v-if="c.action" class="table-link" @click="c.action(row)">{{c.format?c.format(row[c.key],row):row[c.key]??'—'}}</button><template v-else>{{c.format?c.format(row[c.key],row):row[c.key]??'—'}}</template></td></tr></tbody></table></div></template>
